"use strict";

// The most direct form the family has: the imported member call IS the
// key. There is no local wrapper between the class definition and the
// sink, so nothing here depends on resolving a local callable -- only on
// the key being executed code at all.
const danger = require("./danger");

class DirectImportedCall {
  [danger.explode("direct-member-call")]() {}
}

module.exports = DirectImportedCall;
